package com.aistock.gateway;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController public class AnalysisApiProxyController {
 private final ForecastPublicClient client;private final ObjectMapper mapper;public AnalysisApiProxyController(ForecastPublicClient client,ObjectMapper mapper){this.client=client;this.mapper=mapper;}
 @RequestMapping({"/api/v1/stock-analyses","/api/v1/stock-analyses/**"})public ResponseEntity<byte[]> proxy(HttpServletRequest request,@RequestParam Map<String,String> query){var path=request.getRequestURI();var method=request.getMethod();if(!ProxyHeaderPolicy.allowed(method,path))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);byte[] body=new byte[0];if("POST".equals(method)){try{body=request.getInputStream().readNBytes(2049);}catch(java.io.IOException e){throw new BusinessException("VALIDATION_FAILED","请求格式不正确",HttpStatus.BAD_REQUEST);}if(body.length>2048)throw new BusinessException("PREDICTION_REQUEST_INVALID","预测请求超过处理上限",HttpStatus.PAYLOAD_TOO_LARGE);}try{var safe=new LinkedHashMap<String,String>();for(String key:path.endsWith("/prediction-options")?List.of("page","instrumentId"):List.of("page","instrumentId","from","to"))if(query.containsKey(key))safe.put(key,query.get(key));var headers=ProxyHeaderPolicy.request(request);var relative=path.substring(8);var response=switch(method){case "GET"->client.get(relative,safe,headers);case "POST"->client.post(relative,headers,body);case "OPTIONS"->client.options(relative,headers);default->throw new IllegalStateException();};return ResponseEntity.status(response.getStatusCode()).headers(ProxyHeaderPolicy.response(response.getHeaders())).body(response.getBody());}catch(feign.FeignException e){if(e.status()>=400&&e.status()<500){try{var n=mapper.readTree(e.contentUTF8());if(n.hasNonNull("code")&&n.hasNonNull("message")&&n.path("data").isNull())return ResponseEntity.status(e.status()).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","no-store").body(mapper.writeValueAsBytes(ApiResponse.failure(n.path("code").asText(),n.path("message").asText(),TraceIds.normalize(request.getHeader("X-Trace-Id")))));}catch(java.io.IOException ignored){}if(e.status()==403)throw new BusinessException("ACCESS_DENIED","请求来源或权限不允许",HttpStatus.FORBIDDEN);}throw unavailable();}catch(RuntimeException e){throw unavailable();}}
 private BusinessException unavailable(){return new BusinessException("PREDICTION_SERVICE_UNAVAILABLE","预测服务暂不可用，请通过原请求查询状态",HttpStatus.SERVICE_UNAVAILABLE);}
}
